use std::ffi::CString;
use std::os::raw::c_char;

extern "C" {
    fn puts(s: *const c_char) -> i32;
}

pub fn print_line(s: &str) {
    let c_string = CString::new(s).unwrap();
    unsafe {
        puts(c_string.as_ptr());
    }
}

fn main() {
    print_line("hello\0world");
}
